\title{A Combinatorial Theory of Simple Normality for Digit Streams}
\author{Aristotle}
\date{2026-06-25}

\begin{document}
\maketitle

\begin{abstract}
Simple normality of a real number in base $b$ --- the requirement that every digit
$0,1,\ldots,b-1$ occur in its base-$b$ expansion with limiting relative frequency exactly
$1/b$ --- is the gateway to some of the most stubborn open problems in number theory,
including the conjectured normality of $\pi$, $e$, and $\sqrt{2}$. We develop a
self-contained, purely combinatorial theory of simple normality by abstracting away the
real-analytic packaging of base-$b$ expansions and working directly with \emph{digit
streams} $s : \mathbb{N} \to \{0,\ldots,b-1\}$. We introduce the digit count
$\countDigit(s,d,n)$, the empirical frequency $\freq(s,d,n)$, and the predicate
$\SimplyNormal(s)$, and prove four foundational results: (1) the \emph{conservation law}
$\sum_d \countDigit(s,d,n) = n$, which exhibits the empirical frequency vector as a point of
the probability simplex $\Delta^{b-1}$ via $\sum_d \freq(s,d,n) = 1$; (2) a
\emph{monotone-divergence criterion} showing that any digit occurring infinitely often has
unbounded, divergent count; (3) the \emph{single-coordinate obstruction}, that convergence of
even one frequency coordinate to a value $\neq 1/b$ forbids normality; and (4) an explicit
\emph{periodic simply normal stream}, the cyclic stream $\cyc_b(k) = k \bmod b$, which is
rational yet simply normal, thereby refuting the folklore implication ``normal $\Rightarrow$
irrational/transcendental.'' We close with a research program connecting these combinatorial
primitives to equidistribution and ergodic theory.

\medskip
\noindent\textbf{Keywords.} Simple normality, normal numbers, digit streams, empirical
frequency, probability simplex, equidistribution, discrepancy, cyclic sequence, conservation
law.
\end{abstract}

\section{Introduction}

\subsection{Background and motivation}
Borel introduced normal numbers in 1909 and proved that almost every real number (with respect
to Lebesgue measure) is normal in every base. Yet more than a century later, the normality of
essentially every \emph{naturally arising} constant remains open: it is not known whether
$\pi$, $e$, $\sqrt{2}$, $\ln 2$, or $\zeta(3)$ is even \emph{simply} normal in \emph{any} single
base, despite trillions of computed digits showing no statistical anomaly. The gulf between the
measure-theoretic abundance of normal numbers and our inability to certify a single explicit
constant is one of the defining frustrations of the field.

Faced with this gulf, a productive strategy is to set aside the specific-constant question and
instead build a \emph{robust theory of the property itself}: identify the correct primitive
object, establish its conservation laws, and classify what is provable about which sequences are
normal. This paper carries out that program for \emph{simple normality}.

\subsection{The central abstraction}
The essential move is to discard the real number and retain only its digit stream. A real
number's base-$b$ expansion is encumbered by non-uniqueness ($0.4\overline{9} = 0.5\overline{0}$)
and by the analytic baggage of convergent series; neither is relevant to the \emph{frequency}
statement that normality really is. We therefore study sequences
\[
s : \mathbb{N} \to \Fin b, \qquad \Fin b = \{0,1,\ldots,b-1\},
\]
and define normality intrinsically on the stream. This turns every question into finite
combinatorics plus a single limit.

\subsection{Contributions}
We prove, with full formal rigor (machine-checked), the following.
\begin{enumerate}
  \item \textbf{Conservation law} (Theorem~\ref{thm:cons}): $\sum_{d} \countDigit(s,d,n) = n$.
  \item \textbf{Simplex constraint} (Theorem~\ref{thm:simplex}): for $n>0$,
        $\sum_d \freq(s,d,n) = 1$, so each frequency vector lies in $\Delta^{b-1}$.
  \item \textbf{Monotonicity and divergence} (Theorems~\ref{thm:mono}--\ref{thm:div}).
  \item \textbf{Single-coordinate obstruction} (Theorem~\ref{thm:obstr}).
  \item \textbf{Periodic normal witness} (Theorems~\ref{thm:per}--\ref{thm:exists}).
\end{enumerate}

\section{Definitions}
Throughout fix a base $b \in \mathbb{N}$ (with $b \ge 1$ for the simplex statements, $b \ge 2$
for nontrivial normality). Write $\Fin b = \{0,\ldots,b-1\}$ for the digit alphabet and
$[n] = \{0,\ldots,n-1\}$.

\begin{definition}[Digit stream]
A \emph{base-$b$ digit stream} is a function $s : \mathbb{N} \to \Fin b$.
\end{definition}

\begin{definition}[Digit count]
For a stream $s$, digit $d \in \Fin b$, window $n \in \mathbb{N}$,
\[
\countDigit(s,d,n) = \#\{k \in [n] : s(k) = d\}.
\]
\end{definition}

\begin{definition}[Empirical frequency]
With the convention $0/0 = 0$,
\[
\freq(s,d,n) = \frac{\countDigit(s,d,n)}{n} \in \mathbb{R}.
\]
The value at $n=0$ is a harmless junk value; substantive statements quantify over $n>0$ or
limits.
\end{definition}

\begin{definition}[Simple normality]
A stream $s$ is \emph{simply normal}, written $\SimplyNormal(s)$, if for every $d \in \Fin b$,
\[
\lim_{n \to \infty} \freq(s,d,n) = \frac{1}{b}.
\]
\end{definition}

\begin{remark}
Simple normality is the $k=1$ layer of full normality (which controls all length-$k$ blocks).
It already exhibits the conservation, obstruction, and separation phenomena.
\end{remark}

\section{The conservation law and monotone divergence}

\begin{theorem}[Count bound; \texttt{countDigit\_le}]\label{thm:bound}
For all $s,d,n$ we have $\countDigit(s,d,n) \le n$.
\end{theorem}
\begin{proof}[Proof sketch]
The set $\{k<n : s(k)=d\}$ is a subset of $[n]$ and cardinality is monotone under inclusion.
\end{proof}

\begin{theorem}[Conservation law; \texttt{sum\_countDigit}]\label{thm:cons}
For every stream $s$ and window $n$,
\[
\sum_{d \in \Fin b} \countDigit(s,d,n) = n.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Partition $[n]$ by the value of $s$. The fibers $\{k \in [n] : s(k)=d\}$ are pairwise disjoint
and cover $[n]$, so the fiber-wise cardinality formula gives
$n = \#[n] = \sum_d \#\{k \in [n] : s(k)=d\} = \sum_d \countDigit(s,d,n)$.
\end{proof}

\begin{theorem}[Frequencies form a probability vector; \texttt{sum\_freq}]\label{thm:simplex}
For every stream $s$ and every $n > 0$,
\[
\sum_{d \in \Fin b} \freq(s,d,n) = 1.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Since $n>0$, factor out $1/n$:
$\sum_d \freq(s,d,n) = \frac{1}{n}\sum_d \countDigit(s,d,n) = \frac{n}{n} = 1$,
using Theorem~\ref{thm:cons}.
\end{proof}

\begin{corollary}[Simplex geometry]
For each $n>0$ the vector $\mathbf{f}_n = (\freq(s,0,n),\ldots,\freq(s,b-1,n))$ has
non-negative coordinates summing to $1$, hence lies in the probability simplex
$\Delta^{b-1} \subset \mathbb{R}^b$. Simple normality is exactly
$\mathbf{f}_n \to (1/b,\ldots,1/b)$, the barycenter.
\end{corollary}

\begin{theorem}[Monotonicity; \texttt{countDigit\_monotone}]\label{thm:mono}
For fixed $s,d$, the map $n \mapsto \countDigit(s,d,n)$ is monotone non-decreasing.
\end{theorem}
\begin{proof}[Proof sketch]
If $m \le n$ then $[m] \subseteq [n]$ and the corresponding occurrence sets are nested; apply
monotonicity of cardinality.
\end{proof}

\begin{theorem}[Unbounded count; \texttt{countDigit\_not\_bddAbove}]\label{thm:unbdd}
If $d$ occurs cofinally (for every $N$ there is $k \ge N$ with $s(k)=d$), then the range of
$n \mapsto \countDigit(s,d,n)$ is not bounded above.
\end{theorem}
\begin{proof}[Proof sketch]
By induction on $m$: given $n$ with count $\ge m$, cofinality supplies $k \ge n$ with
$s(k)=d$; then $\countDigit(s,d,k+1) \ge m+1$ (old occurrences are retained since
$[n]\subseteq[k+1]$, plus the new one at $k$). Hence the counts exceed every $m$.
\end{proof}

\begin{theorem}[Divergence; \texttt{countDigit\_tendsto\_atTop}]\label{thm:div}
If $d$ occurs cofinally then $\countDigit(s,d,n) \to +\infty$ as $n \to \infty$.
\end{theorem}
\begin{proof}[Proof sketch]
A monotone sequence of naturals is bounded or diverges to $+\infty$. Theorem~\ref{thm:mono}
gives monotonicity, Theorem~\ref{thm:unbdd} rules out boundedness, hence divergence (the
unbounded-monotone branch of the dichotomy \texttt{monotone\_nat\_unbounded\_eventually\_ge}).
\end{proof}

\section{The obstruction theorem}

\begin{theorem}[Single-coordinate obstruction; \texttt{not\_simplyNormal\_of\_freq\_tendsto}]\label{thm:obstr}
Let $b \ge 2$. If some digit $d$ and real $L \neq 1/b$ satisfy
$\lim_{n} \freq(s,d,n) = L$, then $s$ is not simply normal.
\end{theorem}
\begin{proof}[Proof sketch]
Normality forces $\freq(s,d,\cdot) \to 1/b$; uniqueness of real limits forbids simultaneous
convergence to $L \neq 1/b$.
\end{proof}

\begin{corollary}[Density-zero obstruction; \texttt{freq\_tendsto\_zero\_of\_finite}]
If the set of indices where $d$ appears has density zero (e.g.\ finite, or factorial-supported
with counting function $o(n)$), then $\freq(s,d,\cdot) \to 0 \neq 1/b$, so $s$ is not simply
normal.
\end{corollary}

\section{A periodic simply normal stream}

\begin{definition}[Cyclic stream]
The \emph{cyclic} stream in base $b$ is $\cyc_b(k) = k \bmod b$, enumerating
$0,1,\ldots,b-1,0,1,\ldots$ forever.
\end{definition}

\begin{theorem}[Periodicity; \texttt{cyc\_periodic}]\label{thm:per}
$\cyc_b(k+b) = \cyc_b(k)$ for all $k$.
\end{theorem}
\begin{proof}[Proof sketch]
$(k+b) \bmod b = k \bmod b$.
\end{proof}

Periodicity makes $\cyc_b$ the digit stream of a \emph{rational} number (purely periodic
expansion), hence algebraic of degree $1$.

\begin{theorem}[Exact count and bounds; \texttt{cyc\_count\_bounds}]\label{thm:cyccount}
For all $d \in \Fin b$ and $n$,
\[
\countDigit(\cyc_b, d, n) = \left\lfloor \frac{n}{b} \right\rfloor + [\, d < n \bmod b \,],
\]
with Iverson bracket $[\cdot] \in \{0,1\}$. Hence
$\lfloor n/b\rfloor \le \countDigit(\cyc_b,d,n) \le \lfloor n/b\rfloor + 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Each of the $\lfloor n/b\rfloor$ complete blocks contributes one occurrence of $d$; the
trailing partial block $\{0,\ldots,(n \bmod b)-1\}$ contains $d$ iff $d < n \bmod b$. This is the
congruence count \texttt{Nat.count\_modEq\_card}.
\end{proof}

\begin{theorem}[Cyclic normality; \texttt{cyc\_simplyNormal}]\label{thm:cycnorm}
For every $b \ge 1$, the cyclic stream $\cyc_b$ is simply normal.
\end{theorem}
\begin{proof}[Proof sketch]
Divide the bounds of Theorem~\ref{thm:cyccount} by $n>0$:
$\frac{\lfloor n/b\rfloor}{n} \le \freq(\cyc_b,d,n) \le \frac{\lfloor n/b\rfloor}{n} + \frac1n$.
Since $\lfloor n/b\rfloor = (n - (n \bmod b))/b$ with $0 \le n\bmod b < b$,
$\frac{\lfloor n/b\rfloor}{n} = \frac1b - \frac{n \bmod b}{bn} \to \frac1b$, and the extra
$1/n \to 0$. Squeeze.
\end{proof}

\begin{theorem}[Existence; \texttt{exists\_periodic\_simplyNormal}]\label{thm:exists}
For every $b \ge 1$ there exists a periodic simply normal stream, namely $\cyc_b$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorems~\ref{thm:per} and \ref{thm:cycnorm}.
\end{proof}

\begin{corollary}[Normality does not imply transcendence]
A simply normal real need not be irrational: the number with digit stream $\cyc_b$ is rational
yet simply normal. The folklore ``simply normal $\Rightarrow$ irrational $\Rightarrow$
transcendental'' fails at its first link.
\end{corollary}

\begin{remark}[Discrepancy $O(1)$]
With $D(d,n) = |\countDigit(s,d,n) - n/b|$, Theorem~\ref{thm:cyccount} gives
$D(\cyc_b,d,n) \le 1$ uniformly: the cyclic stream achieves the smallest possible, bounded
discrepancy --- the extreme endpoint of equidistribution, reached by rigid block structure
rather than statistical randomness.
\end{remark}

\section{Applications and the equidistribution bridge}

\subsection{Algorithmic verification}
The definitions are directly computable: $\countDigit$ and $\freq$ in $O(n)$ time, discrepancy in
$O(b+n)$. This enables rigorous finite-window auditing of candidate constants, certifying
closeness to uniform and exhibiting obstructions (Theorem~\ref{thm:obstr}) when present.

\subsection{The equidistribution bridge}
For $x \in [0,1)$ the $n$-th base-$b$ digit is
$s_x(n) = \lfloor b \cdot (b^{n-1} x \bmod 1)\rfloor$, read from the orbit of $x$ under
$T_b(y) = by \bmod 1$. Hence
\[
\countDigit(s_x,d,n) = \sum_{j=0}^{n-1} \mathbf{1}_{[d/b,(d+1)/b)}\big(T_b^{\,j}(x)\big),
\]
a Birkhoff sum. Simple normality of $x$ is equivalent to equidistribution of $(T_b^j x)_j$ on
$[0,1)$, with digit-frequency limits equal to the lengths $1/b$ of the subintervals. This is the
conduit through which ergodicity of $T_b$ yields Borel's almost-everywhere normality.

\section{Future directions}

\paragraph{FD1. Frequency-vector convergence is the only obstruction.}
\emph{Conjecture:} $s$ is simply normal iff its empirical vectors $\mathbf{f}_n \in \Delta^{b-1}$
converge to the uniform vector, and partial convergence of one coordinate to $\neq 1/b$ forbids
normality. The simplex constraint (Theorem~\ref{thm:simplex}) and the one-coordinate obstruction
(Theorem~\ref{thm:obstr}) are in hand; closing the iff needs a Prokhorov-style compactness
argument on $\Delta^{b-1}$.

\paragraph{FD2. Block-discrepancy bound $\Rightarrow$ normality, quantitatively.}
\emph{Conjecture:} if $|\countDigit(s,d,n) - n/b| \le C n^{1-\varepsilon}$ uniformly, then $s$ is
simply normal with rate $O(n^{-\varepsilon})$. The cyclic stream is the extreme case
$C=1,\varepsilon=1$; the squeeze in Theorem~\ref{thm:cycnorm} is exactly the $\varepsilon=1$
instance.

\paragraph{FD3. Normality independent of transcendence (both directions).}
\emph{Conjecture:} there exist algebraic simply-normal streams and transcendental non-normal
streams. Direction (i) is proved (Theorem~\ref{thm:exists}); direction (ii) reduces to a
density-zero obstruction for the factorial support $\{k! : k\}$ with counting function
$O(\log n)$.

\paragraph{FD4. Equidistribution bridge.}
\emph{Conjecture:} $x$ is simply normal in base $b$ iff $(b^n x \bmod 1)$ is equidistributed on
$[0,1)$, with digit-frequency limits equal to the Lebesgue measures of $[d/b,(d+1)/b)$. The
digit is the floor of $b\cdot(b^{n-1}x \bmod 1)$, so $\countDigit$ is a Birkhoff sum along the
$\times b$ map, linking the combinatorial theory to ergodic theory and the Weyl criterion.

\section{Conclusion}
By treating normality as a frequency property of digit streams, we obtain a clean, fully
formalized foundation: a conservation law placing frequencies on the probability simplex, a
monotone-divergence principle, a sharp single-coordinate obstruction, and an explicit periodic
witness detaching normality from transcendence. The grand questions about $\pi$, $e$, $\sqrt{2}$
remain open, but are now stated precisely and equipped with scaffolding for quantitative and
dynamical attacks.

\end{document}

