function countDigit(s, d, n):
    c <- 0
    for k in 0 .. n-1:
        if s(k) == d: c <- c + 1
    return c

function freq(s, d, n):
    if n == 0: return 0        # junk value, harmless (atTop statement)
    return countDigit(s, d, n) / n

function frequencyVector(s, b, n):
    return [ freq(s, d, n) for d in 0 .. b-1 ]   # lies on Delta^{b-1}

