function detect_obstruction(s, b, n, tol):
    target <- 1 / b
    for d in 0 .. b-1:
        f <- countDigit(s, d, n) / n
        if |f - target| > tol:
            return d        # certificate: digit d violates uniformity
    return None             # no obstruction in this window
